package com.example.starter.domain;

/** 实验状态：OPEN 可继续分配，CLOSED 拒绝新增分配但保留历史结果。 */
public enum ExperimentStatus {
    OPEN,
    CLOSED
}

package com.example.starter.domain;

/** 实验处理代码，仅保存于数据库映射表，不对普通查询暴露。 */
public enum TreatmentCode {
    A,
    B
}

package com.example.starter.domain;

/**
 * 参与者分配状态：ENROLLED 在组，WITHDRAWN 已退组（席位保留、不重排）。
 */
public enum AllocationStatus {
    ENROLLED,
    WITHDRAWN
}

package com.example.starter.domain;

/** 揭盲申请状态：PENDING 待审，APPROVED 已批准（揭盲结果可被申请人查询）。 */
public enum UnblindStatus {
    PENDING,
    APPROVED
}

package com.example.starter.domain;

import java.util.Objects;

/**
 * 操作者身份，来自受信任的本地测试请求头 X-Actor-Id / X-Role。
 *
 * @param actorId 操作者编号
 * @param role    操作者角色
 */
public record Actor(String actorId, Role role) {

    /** 受信任角色：COORDINATOR 协调员，REVIEWER 审阅员。 */
    public enum Role {
        COORDINATOR,
        REVIEWER
    }

    public Actor {
        Objects.requireNonNull(actorId, "actorId");
        Objects.requireNonNull(role, "role");
    }
}

