package com.example.starter.web.dto;

import jakarta.validation.constraints.Max;
import jakarta.validation.constraints.Min;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;

/**
 * 创建实验请求。
 *
 * @param experimentId 实验唯一编号
 * @param blockCount   固定区组数量，范围 2～8
 */
public record CreateExperimentRequest(
        @NotBlank String experimentId,
        @NotNull @Min(2) @Max(8) Integer blockCount
) {
}

package com.example.starter.web.dto;

import jakarta.validation.constraints.NotBlank;

/**
 * 参与者登记请求。
 *
 * @param participantId 合成参与者编号
 * @param requestId     全局唯一写操作请求编号
 */
public record EnrollRequest(
        @NotBlank String participantId,
        @NotBlank String requestId
) {
}

package com.example.starter.web.dto;

import jakarta.validation.constraints.NotBlank;

/**
 * 参与者退组请求；席位保留，不重排已有分配。
 *
 * @param participantId 合成参与者编号
 * @param requestId     全局唯一写操作请求编号
 */
public record WithdrawRequest(
        @NotBlank String participantId,
        @NotBlank String requestId
) {
}

package com.example.starter.web.dto;

import jakarta.validation.constraints.NotBlank;

/**
 * 关闭实验请求。
 *
 * @param requestId 全局唯一写操作请求编号
 */
public record CloseExperimentRequest(
        @NotBlank String requestId
) {
}

package com.example.starter.web.dto;

import jakarta.validation.constraints.NotBlank;

/**
 * 揭盲申请请求：协调员为已分配参与者提出带原因的申请。
 *
 * @param participantId 被申请揭盲的参与者编号
 * @param reason        揭盲原因
 * @param requestId     全局唯一写操作请求编号
 */
public record UnblindRequestRequest(
        @NotBlank String participantId,
        @NotBlank String reason,
        @NotBlank String requestId
) {
}

package com.example.starter.web.dto;

import jakarta.validation.constraints.NotBlank;

/**
 * 批准揭盲申请请求；必须由非申请人的 REVIEWER 执行。
 *
 * @param requestId 全局唯一写操作请求编号
 */
public record ApproveUnblindRequest(
        @NotBlank String requestId
) {
}

