 * @param participantId 参与者编号
 * @param reason        申请原因
 * @param applicantId   申请人（协调员）编号
 * @param status        申请状态（PENDING / APPROVED）
 */
public record UnblindRequestView(
        String requestId,
        String experimentId,
        String participantId,
        String reason,
